(()=>{'use strict';const {$,esc:E}=Q;let client=null;const allowed=k=>/^(fqFav|fqHadithFav|fqLang|fq:(ayah|passage):[0-9]+:[0-9]+(?:[^0-9][0-9]+)?)$/.test(k);function backup(){const items={};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(allowed(k))items[k]=localStorage.getItem(k);}return {format:'famous-quran-backup',version:1,created:new Date().toISOString(),items};}function validate(x){if(x?.format!=='famous-quran-backup'||x.version!==1||!x.items||Array.isArray(x.items)||Object.keys(x.items).length>10000)throw Error('Invalid backup');for(const [k,v]of Object.entries(x.items)){if(!allowed(k)||typeof v!=='string'||v.length>100000)throw Error('Invalid backup entry');if(k==='fqLang'&&!['en','bn','ja'].includes(v))throw Error('Invalid language');if(k==='fqFav'){const a=JSON.parse(v);if(!Array.isArray(a)||!a.every(n=>Number.isInteger(n)&&n>=1&&n<=30))throw Error('Invalid favorites');}if(k==='fqHadithFav'){const a=JSON.parse(v);if(!Array.isArray(a)||!a.every(n=>/^\d+$/.test(String(n))))throw Error('Invalid hadith IDs');}}return x;}function restore(x){validate(x);for(const [k,v]of Object.entries(x.items)){if(k==='fqFav'||k==='fqHadithFav'){const a=Q.get(k,[]);Q.set(k,[...new Set([...(Array.isArray(a)?a:[]),...JSON.parse(v)])]);}else if(!Q.raw(k))Q.rawSet(k,v);}Q.render();Q.notify();Q.toast(Q.t('complete'));}
async function supabase(){if(client)return client;const c=window.FQ_CONFIG;if(!c?.supabaseUrl||!c?.publishableKey)throw Error('Supabase not configured');if(!window.supabase)await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.js';s.onload=resolve;s.onerror=reject;document.head.append(s);});client=window.supabase.createClient(c.supabaseUrl,c.publishableKey,{auth:{flowType:'pkce',detectSessionInUrl:true}});return client;}
Q.account=async()=>{Q.panel(Q.t('account'),`<p>${E(Q.t('noteHelp'))}</p><div class="control-row"><button class="btn" id="exportBackup">${E(Q.t('backup'))}</button><label class="btn">${E(Q.t('restore'))}<input id="importBackup" type="file" accept="application/json" hidden></label></div><div id="authArea"></div><p id="accountStatus" role="status"></p>`);$('#exportBackup').onclick=()=>Q.download(new Blob([JSON.stringify(backup(),null,2)],{type:'application/json'}),'famous-quran-backup.json');$('#importBackup').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5*1048576)throw Error('Backup exceeds 5 MB');restore(JSON.parse(await f.text()));}catch(err){$('#accountStatus').textContent=String(err.message);}};if(!window.FQ_CONFIG?.supabaseUrl||!window.FQ_CONFIG?.publishableKey){$('#authArea').innerHTML=`<p>${E(Q.t('authPending'))}</p>`;return;}try{const sb=await supabase(),{data:{session}}=await sb.auth.getSession();if(!$('#utilityDialog').open)return;if(session){$('#authArea').innerHTML=`<p>${E(session.user.email)}</p><button class="btn" id="signOut">${E(Q.t('signOut'))}</button><div class="control-row"><button class="btn" id="cloudSave">${E(Q.t('backup'))} (cloud)</button><button class="btn" id="cloudRestore">${E(Q.t('restore'))} (cloud)</button></div>`;$('#signOut').onclick=async()=>{const {error}=await sb.auth.signOut();if(error)Q.toast(error.message);else Q.account();};$('#cloudSave').onclick=async()=>{const {error}=await sb.from('fq_backups').upsert({user_id:session.user.id,payload:backup(),updated_at:new Date().toISOString()});$('#accountStatus').textContent=error?error.message:Q.t('saved');};$('#cloudRestore').onclick=async()=>{const {data,error}=await sb.from('fq_backups').select('payload').eq('user_id',session.user.id).maybeSingle();if(error)$('#accountStatus').textContent=error.message;else if(data)restore(data.payload);else $('#accountStatus').textContent=Q.t('noSaved');};}else{$('#authArea').innerHTML=`<form id="emailSignIn"><label for="email">${E(Q.t('email'))}</label><input class="field" id="email" type="email" required autocomplete="email"><button class="btn primary">${E(Q.t('sendLink'))}</button></form>${window.FQ_CONFIG.googleEnabled?`<button class="btn" id="googleSignIn">${E(Q.t('google'))}</button>`:''}`;$('#emailSignIn').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const {error}=await sb.auth.signInWithOtp({email:$('#email').value,options:{emailRedirectTo:location.origin+'/'}});$('#accountStatus').textContent=error?error.message:Q.t('authSent');}catch(err){$('#accountStatus').textContent=err.message;}finally{b.disabled=false;}};if($('#googleSignIn'))$('#googleSignIn').onclick=async()=>{const {error}=await sb.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/'}});if(error)$('#accountStatus').textContent=error.message;};}}catch(err){$('#accountStatus').textContent=Q.t('sourceError')+' '+(err.message||'');}};$('#accountOpen').onclick=Q.account;if(location.search.includes('code=')&&window.FQ_CONFIG?.supabaseUrl)supabase().then(()=>Q.account()).catch(()=>Q.toast(Q.t('sourceError')));})();
